#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.164528075, 0.289029255, 0.004108914999999991], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.11423024500000001, 'zmax': 0.114230245, 'profiles': [{'outer': [[-0.195225695, -0.134801135], [-0.190721325, -0.09955255499999999], [-0.17460579113991345, -0.08127225005739147], [-0.17225099500000002, -0.07822225499999999], [-0.17173890415478482, -0.07802025922797531], [-0.15559192500000002, -0.059704284999999996], [-0.129113735, -0.031796145], [-0.10883212500000002, -0.011490685], [-0.07425083500000002, 0.02740426500000004], [0.07425082499999999, 0.02740426500000004], [0.09248285499999999, 0.00483472500000004], [0.129375895, -0.031676994999999986], [0.173228095, -0.07698301499999999], [0.190721315, -0.09955255499999999], [0.195225695, -0.134801135], [0.19091197499999998, -0.163019105], [0.17620719499999998, -0.182061415], [0.15106367499999998, -0.210970535], [-0.15106370500000002, -0.210970535], [-0.17620722500000002, -0.182061415], [-0.190911995, -0.163019105]], 'holes': []}, {'outer': [[-0.08330179500000001, 0.03296031500000002], [-0.08330179500000001, 0.04121227500000002], [-0.087472505, 0.04121227500000002], [-0.087472505, 0.04491336500000004], [-0.03187785500000001, 0.04491336500000004], [-0.024430955000000008, 0.08101858500000003], [-0.03867624500000001, 0.08101858500000003], [-0.04351785500000001, 0.08694477500000003], [-0.04351785500000001, 0.09280397500000004], [-0.03867624500000001, 0.09783567500000001], [-0.018314645000000008, 0.09783567500000001], [-0.01484836500000001, 0.12971420500000003], [-0.02360351500000001, 0.12971420500000003], [-0.02531429500000001, 0.132140655], [-0.02360351500000001, 0.13483537500000004], [-0.02244064500000001, 0.137071685], [-0.02361469500000001, 0.13842470500000004], [-0.02360351500000001, 0.139632245], [-0.006294485000000009, 0.139632245], [-0.006294485000000009, 0.181741965], [-0.00881033500000001, 0.181741965], [-0.00961540500000001, 0.182759475], [-0.00881033500000001, 0.18377704500000003], [-0.005862231081848299, 0.18377704500000003], [-0.00648456500000001, 0.183899955], [-0.01104664500000001, 0.186952605], [-0.01409920500000001, 0.191514625], [-0.01517263500000001, 0.196904075], [-0.01409920500000001, 0.202282505], [-0.01104664500000001, 0.206844525], [-0.00648456500000001, 0.209897055], [-0.0011062450000000092, 0.21097053500000001], [0.004283264999999991, 0.209897055], [0.00884533499999999, 0.206844525], [0.011897894999999992, 0.202282505], [0.01297132499999999, 0.196904075], [0.011897894999999992, 0.191514625], [0.00884533499999999, 0.186952605], [0.004283264999999991, 0.183899955], [0.0036596362692406527, 0.18377704500000003], [0.006541934999999991, 0.18377704500000003], [0.00733582499999999, 0.182759475], [0.006541934999999991, 0.181741965], [0.004026084999999991, 0.181741965], [0.004026084999999991, 0.139632245], [0.02133511499999999, 0.139632245], [0.02133511499999999, 0.13842470500000004], [0.02016105499999999, 0.137071685], [0.02133511499999999, 0.13483537500000004], [0.02303471499999999, 0.132140655], [0.02133511499999999, 0.12971420500000003], [0.01256878499999999, 0.12971420500000003], [0.01604625499999999, 0.09783567500000001], [0.03639666499999999, 0.09783567500000001], [0.04123827499999999, 0.09280397500000004], [0.04123827499999999, 0.08694477500000003], [0.03639666499999999, 0.08101858500000003], [0.02215137499999999, 0.08101858500000003], [0.02960946499999999, 0.04491336500000004], [0.085204115, 0.04491336500000004], [0.085204115, 0.04121227500000002], [0.08103340499999999, 0.04121227500000002], [0.08103340499999999, 0.03296031500000002], [0.085204115, 0.03296031500000002], [0.085204115, 0.02778329500000004], [-0.087472505, 0.02778329500000004], [-0.087472505, 0.03296031500000002]], 'holes': []}], 'simplify_tolerance': 8.4388214e-05, 'sketch_entity_count': 88}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
